package cn.codedog.service;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@Service public class RankingCompletenessService {
 private final JdbcTemplate j;public RankingCompletenessService(JdbcTemplate j){this.j=j;}
 public Map<String,Object> panel(String owner){return Map.of("missingPhones",j.queryForList("SELECT DISTINCT s.student_id,s.student_name FROM ranking_students s WHERE s.owner_username=? AND NOT EXISTS(SELECT 1 FROM ranking_student_accounts a WHERE a.owner_username=s.owner_username AND a.student_id=s.student_id) AND NOT EXISTS(SELECT 1 FROM ranking_current_ownership o WHERE o.student_id=s.student_id AND (o.state<>'ACTIVE' OR o.owner_username<>s.owner_username))",owner),"pendingAccounts",j.queryForList("SELECT DISTINCT s.student_id,s.student_name FROM ranking_students s LEFT JOIN ranking_student_accounts a ON a.owner_username=s.owner_username AND a.student_id=s.student_id WHERE s.owner_username=? AND (a.id IS NULL OR a.enabled=FALSE) AND NOT EXISTS(SELECT 1 FROM ranking_current_ownership o WHERE o.student_id=s.student_id AND (o.state<>'ACTIVE' OR o.owner_username<>s.owner_username))",owner),"importErrors",j.queryForList("SELECT id,source_name,rejected_rows,status,created_at FROM ranking_import_batches WHERE owner_username=? AND rejected_rows>0 ORDER BY id DESC LIMIT 100",owner),"missingLessons",j.queryForList("SELECT e.*,s.student_id,s.student_name FROM ranking_expected_lessons e JOIN ranking_students s ON s.owner_username=e.owner_username AND s.camp_id=e.camp_id AND s.class_id=e.class_id LEFT JOIN ranking_lesson_results r ON r.owner_username=e.owner_username AND r.camp_id=e.camp_id AND r.class_id=e.class_id AND r.lesson_id=e.lesson_id AND r.student_id=s.student_id WHERE e.owner_username=? AND e.planned_at<CURRENT_TIMESTAMP(6) AND r.student_id IS NULL AND NOT EXISTS(SELECT 1 FROM ranking_current_ownership o WHERE o.student_id=s.student_id AND (o.state<>'ACTIVE' OR o.owner_username<>s.owner_username)) ORDER BY e.planned_at DESC LIMIT 500",owner),"missingDates",j.queryForList("SELECT camp_id,class_id,lesson_id,lesson_name FROM ranking_lessons WHERE owner_username=? AND ended_at IS NULL",owner));}
 public List<Map<String,Object>> expected(String owner){return j.queryForList("SELECT * FROM ranking_expected_lessons WHERE owner_username=? ORDER BY planned_at DESC",owner);}
 public record Expected(String campId,String classId,String lessonId,String lessonName,java.time.Instant plannedAt){}
 @Transactional public Map<String,Object> save(String owner,Long id,Expected e){if(e.campId()==null||e.classId()==null||e.lessonId()==null||e.lessonId().isBlank()||e.lessonName()==null||e.lessonName().isBlank()||e.plannedAt()==null)throw RankingPointsService.conflict("请填写营期、班级、课节ID、名称和预计时间");if(j.queryForObject("SELECT COUNT(*) FROM ranking_classes WHERE owner_username=? AND camp_id=? AND class_id=?",Integer.class,owner,e.campId(),e.classId())!=1)throw RankingPointsService.conflict("班级不属于当前老师");
 var before=id==null?List.of():j.queryForList("SELECT * FROM ranking_expected_lessons WHERE id=? AND owner_username=? FOR UPDATE",id,owner);if(id!=null&&before.isEmpty())throw RankingPointsService.conflict("课节不存在");if(id==null)j.update("INSERT INTO ranking_expected_lessons(owner_username,camp_id,class_id,lesson_id,lesson_name,planned_at) VALUES(?,?,?,?,?,?)",owner,e.campId(),e.classId(),e.lessonId(),e.lessonName(),java.sql.Timestamp.from(e.plannedAt()));else j.update("UPDATE ranking_expected_lessons SET camp_id=?,class_id=?,lesson_id=?,lesson_name=?,planned_at=? WHERE id=? AND owner_username=?",e.campId(),e.classId(),e.lessonId(),e.lessonName(),java.sql.Timestamp.from(e.plannedAt()),id,owner);return Map.of("before",before,"after",e);}
 @Transactional public Map<String,Object> delete(String owner,long id){var before=j.queryForList("SELECT * FROM ranking_expected_lessons WHERE id=? AND owner_username=? FOR UPDATE",id,owner);if(before.isEmpty())throw RankingPointsService.conflict("课节不存在");j.update("DELETE FROM ranking_expected_lessons WHERE id=? AND owner_username=?",id,owner);return Map.of("before",before);}
}
